from pysat.solvers import Solver

def at_least_k(vars_list, k):
    n = len(vars_list)
    if k == 0:
        return [], max(vars_list) if vars_list else 0
    if k > n:
        return [[1, -1]], max(vars_list) if vars_list else 0
    clauses = []
    max_var = max(vars_list)
    s = {}
    def s_var(i,j):
        nonlocal max_var
        if (i,j) not in s:
            max_var += 1
            s[(i,j)] = max_var
        return s[(i,j)]

    for i in range(1, n+1):
        for j in range(1, min(i,k)+1):
            if i == 1 and j == 1:
                clauses.append([-vars_list[0], s_var(i,j)])
            elif j == 1:
                clauses.append([-vars_list[i-1], s_var(i,j)])
                clauses.append([s_var(i-1,j), s_var(i,j)])
            elif i == j:
                clauses.append([-vars_list[i-1], s_var(i-1,j-1)])
                clauses.append([-s_var(i-1,j-1), s_var(i,j)])
            else:
                clauses.append([-vars_list[i-1], s_var(i-1,j-1), s_var(i,j)])
                clauses.append([-s_var(i-1,j), s_var(i,j)])
                clauses.append([-vars_list[i-1], -s_var(i-1,j-1), s_var(i,j)])
    clauses.append([s_var(n,k)])
    return clauses, max_var

# Test: 3 variables, at least 2 true
clauses, mv = at_least_k([1,2,3], 2)
print("Clauses:", clauses)
with Solver(name='g3') as solver:
    for c in clauses:
        solver.add_clause(c)
    sat = solver.solve()
    print("SAT:", sat)
    if sat:
        model = solver.get_model()
        print("Model:", model)
        print("Len:", len(model))
